<script setup lang="ts">
import {computed} from 'vue'
import {isRules,parsePercent,parseMoney,type Rules} from '@/api/modules/finance'
export interface ShareDraft {party:string;percent:string;role:string}
export interface FeeDraft {category:string;party:string;amount:string;basis:string;refund:string}
export interface LineDraft {id:string;shares:ShareDraft[];fees:FeeDraft[]}
export interface RulesDraft {version:string;time:string;condition:string;terms:string;lines:LineDraft[]}
const props=defineProps<{draft:RulesDraft;parties:string[];disabled?:boolean}>()
const labels={SUPPLIER:'服务提供方',PLATFORM:'平台',MCN:'直接 MCN',RIGHTSHOLDER:'权利持有人',PRODUCER:'制作方',PARTICIPANT:'参与方'}
const emit=defineEmits<{change:[value:Rules|null]}>()
const payload=computed(()=>{const d=props.draft;const value={version:d.version.trim(),settlement_at:d.time&&Number.isFinite(Date.parse(d.time))?new Date(d.time).toISOString():'',release_condition:d.condition,terms:d.terms.trim(),lines:d.lines.map(l=>({line_id:l.id,shares:l.shares.map(s=>({party_id:s.party,bps:parsePercent(s.percent),role:s.role})),deductions:l.fees.map(f=>({category:f.category,party_id:f.party,amount_minor:parseMoney(f.amount),basis:f.basis.trim(),refund_behavior:f.refund}))}))};return isRules(value)?value:null})
import {watch} from 'vue'
watch(payload,value=>emit('change',value),{immediate:true})
</script>
<template><section class="supply-card"><h2>结算时间与执行条件</h2><div class="trade-fields two"><label>规则版本 *<input v-model="draft.version" data-testid="finance-rule-version" required maxlength="128" :disabled="disabled"></label><label>可结算日期时间 *<input v-model="draft.time" data-testid="finance-settlement-at" type="datetime-local" required :disabled="disabled"></label></div><label>释放条件 *<select v-model="draft.condition" data-testid="finance-release-condition" required :disabled="disabled"><option value="">明确选择</option><option value="RECEIVED">真实收到款项后</option><option value="DELIVERY_ACCEPTED">真实收到款项且交付已验收</option></select></label></section>
<section class="supply-card"><h2>逐项分配与明确扣除</h2><p class="muted">每项比例合计须为 100%，人民币金额精确到分。最后一位分配方承担整数分舍入余数；约定必须保留原商业佣金。没有扣除时保持扣除列表为空。候选来自原业务，也可明确填写其他实际分配主体编号；服务器核验有效主体，约定仍须独立复核并由各方本人确认。</p><p v-if="!draft.lines.length" class="supply-warning">请先选择真实来源，再按原明细填写分配。</p><div v-for="(line,n) in draft.lines" :key="line.id" class="finance-rule-line"><h3>明细 {{line.id}}</h3><div v-for="(share,k) in line.shares" :key="k" class="trade-fields three"><label>分配主体 *<input v-model.trim="share.party" :data-testid="`finance-share-party-${n}-${k}`" :list="`finance-source-parties-${n}-${k}`" required maxlength="36" placeholder="选择候选或填写实际参与方完整编号" pattern="[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}" :disabled="disabled"><datalist :id="`finance-source-parties-${n}-${k}`"><option v-for="id in parties" :key="id" :value="id">原业务参与主体</option></datalist></label><label>主体角色 *<select v-model="share.role" :data-testid="`finance-share-role-${n}-${k}`" required :disabled="disabled"><option value="">明确选择</option><option v-for="(name,value) in labels" :key="value" :value="value">{{name}}</option></select></label><label>比例（%） *<input v-model="share.percent" :data-testid="`finance-share-percent-${n}-${k}`" inputmode="decimal" placeholder="例如 12.50，须明确填写" required :disabled="disabled"></label><button v-if="line.shares.length>1" type="button" class="danger" :disabled="disabled" @click="line.shares.splice(k,1)">移除分配方</button></div><button type="button" class="outline" :disabled="disabled||line.shares.length>=30" :data-testid="`finance-add-share-${n}`" @click="line.shares.push({party:'',role:'',percent:''})">添加分配方</button><div v-for="(fee,k) in line.fees" :key="k" class="finance-fee"><div class="trade-fields three"><label>扣除类别 *<select v-model="fee.category" :data-testid="`finance-fee-category-${n}-${k}`" :disabled="disabled"><option value="">明确选择</option><option value="CHANNEL_FEE">渠道费用</option><option value="TAX">税费</option><option value="DISCOUNT">折扣</option><option value="OTHER">其他</option></select></label><label>承担主体 *<select v-model="fee.party" :data-testid="`finance-fee-party-${n}-${k}`" :disabled="disabled"><option value="">选择本项分配方</option><option v-for="s in line.shares.filter(s=>s.party)" :key="s.party" :value="s.party">{{s.party}}</option></select></label><label>扣除金额（元） *<input v-model="fee.amount" :data-testid="`finance-fee-amount-${n}-${k}`" inputmode="decimal" :disabled="disabled" required></label></div><label>扣除依据 *<textarea v-model="fee.basis" :data-testid="`finance-fee-basis-${n}-${k}`" maxlength="2000" required :disabled="disabled"></textarea></label><label>退款时处理 *<select v-model="fee.refund" :data-testid="`finance-fee-refund-${n}-${k}`" :disabled="disabled"><option value="">明确选择</option><option value="RETAIN">保留原扣除</option><option value="PROPORTIONAL">按退款比例调整</option></select></label><button class="danger" type="button" :disabled="disabled" @click="line.fees.splice(k,1)">移除扣除</button></div><button type="button" class="outline" :disabled="disabled||line.fees.length>=30" :data-testid="`finance-add-fee-${n}`" @click="line.fees.push({category:'',party:'',amount:'',basis:'',refund:''})">添加明确扣除</button></div></section>
<section class="supply-card"><h2>完整约定条款</h2><label>本次规则与各方责任 *<textarea v-model="draft.terms" data-testid="finance-rule-terms" required maxlength="8000" :disabled="disabled"></textarea></label><p class="muted">保留真实费用、退款和交付条件。渠道账单中的渠道费与税费不得再次作为发行约定的扣除。</p><p v-if="!payload" class="muted">各项比例、时间、角色及条款完整后才可提交。</p></section></template>
